defaultOptionValue:
{{ (() => {
  const memberId = String(appsmith.URL.queryParams.member_id || appsmith.store.member_id || "").trim();
  const isUuid = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/.test(memberId);
  if (!isUuid) return "";
  return (qMembersDirectory.data || []).find(item => String(item.member_id || "") === memberId)?.selection_value || "";
})() }}

sourceData:
{{ [
  { label: "Anonymous cash donor", value: "__anonymous__" },
  ...(tblPendingGivebutterDonations.selectedRow?.provider === "givebutter" ? [
    { label: "Create new individual contributor from donation", value: "__new_individual__" },
    { label: "Create new organization contributor from donation", value: "__new_organization__" }
  ] : []),
  ...(qMembersDirectory.data || []).map(item => ({
    label: `${item.selection_label}${item.email ? " — " + item.email : ""}`,
    value: item.selection_value
  }))
] }}
